def _record(row):
    code, sector_id, name, groups = row
    return {"code": code, "id": sector_id, "name": name, "groups": list(groups), "adult_restricted": code == "U", "coverage_scope": ["india", "global"], "status": "taxonomy_only"}

def list_sectors(include_adult=False):
    return [_record(row) for row in SECTORS if include_adult or row[0] != "U"]

def get_sector(sector_id, include_adult=False):
    return next((item for item in list_sectors(include_adult) if item["id"] == sector_id), None)

def search_sectors(query, include_adult=False):
    needle = query.strip().casefold()
    if not needle:
        return []
    return [item for item in list_sectors(include_adult) if needle in " ".join([item["id"], item["name"], *item["groups"]]).casefold()]

def get_facets():
    return {"work_models": list(WORK_MODELS), "audience_groups": list(AUDIENCE_GROUPS), "delivery_modes": ["offline", "online", "hybrid"], "coverage_scopes": ["india", "global"]}

def validate_catalogue():
    ids = [row[1] for row in SECTORS]
    codes = [row[0] for row in SECTORS]
    return {"valid": len(ids) == len(set(ids)) and len(codes) == len(set(codes)) and len(SECTORS) == 26, "sector_count": len(SECTORS), "unique_ids": len(ids) == len(set(ids)), "unique_codes": len(codes) == len(set(codes)), "adult_excluded_by_default": all(row[0] != "U" for row in SECTORS if row[1] in {x["id"] for x in list_sectors()}), "source_datasets_ingested": False, "legal_coverage_verified": False, "worldwide_exhaustiveness_claimed": False}
